#include <Arduino.h>
#include <SPI.h>

static const int PIN_CS = 17;

void sendReg(uint8_t reg, uint8_t value) {
  digitalWrite(PIN_CS, LOW);
  SPI.transfer(reg);
  SPI.transfer(value);
  digitalWrite(PIN_CS, HIGH);
}

void setup() {
  pinMode(PIN_CS, OUTPUT);
  digitalWrite(PIN_CS, HIGH);
  SPI.setRX(16);
  SPI.setCS(17);
  SPI.setSCK(18);
  SPI.setTX(19);
  SPI.begin();

  Serial1.setTX(0);
  Serial1.setRX(1);
  Serial1.begin(115200);
  Serial1.println("MAX7219_BOOT");

  sendReg(0x0C, 0x01);
  sendReg(0x0F, 0x00);
}

void loop() {
  static uint8_t row = 1;
  static uint8_t pattern = 0x81;
  sendReg(row, pattern);
  row = (row >= 8) ? 1 : (row + 1);
  pattern = (uint8_t)((pattern << 1) | (pattern >> 7));
  Serial1.println("MAX7219_SPI");
  delay(25);
}
